  <script>
    const form = document.getElementById('paymentForm');
    const phoneInput = document.getElementById('phone');
    const phoneError = document.getElementById('phoneError');
    const toast = document.getElementById('toast');

    phoneInput.addEventListener('input', () => {
      phoneInput.classList.remove('invalid');
      phoneError.textContent = '';
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const phone = phoneInput.value.trim();
      const digits = phone.replace(/\D/g, '');
      const validUaePhone = /^(?:\+971|00971|0)?5\d{8}$/.test(digits);

      if (!phone) {
        phoneInput.classList.add('invalid');
        phoneError.textContent = 'يرجى إدخال رقم الجوال.';
        phoneInput.focus();
        return;
      }

      if (!validUaePhone) {
        phoneInput.classList.add('invalid');
        phoneError.textContent = 'يرجى إدخال رقم جوال إماراتي صحيح.';
        phoneInput.focus();
        return;
      }

      showToast('تم تسجيل طلب الدفع بنجاح. سيتم إرسال الإيصال عبر رسالة نصية.');
      form.reset();
    });

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add('show');
      clearTimeout(window.toastTimer);
      window.toastTimer = setTimeout(() => {
        toast.classList.remove('show');
      }, 4000);
    }
